from collections import deque
from string import ascii_lowercase


def fewest_changes(start: str, target: str, words: list[str]) -> int:
    unused = set(words)
    if target not in unused:
        return -1
    unused.discard(start)
    queue = deque([(start, 0)])
    while queue:
        word, changes = queue.popleft()
        if word == target:
            return changes
        for i in range(len(word)):
            for ch in ascii_lowercase:
                nxt = word[:i] + ch + word[i + 1:]
                if nxt in unused:
                    unused.remove(nxt)           # visited when queued: each word enters once
                    queue.append((nxt, changes + 1))
    return -1
